const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const MOD = 1000000007n;
const q = tok[0];
let top = 0;
for (let i = 0; i < q; i++) top = Math.max(top, tok[1 + 2 * i]);
// products of two residues reach 10^18, beyond exact Number range, so the arithmetic uses BigInt
const fact = new Array(top + 1);
fact[0] = 1n;
for (let i = 1; i <= top; i++) fact[i] = fact[i - 1] * BigInt(i) % MOD;
function power(b, e) {
  let r = 1n;
  b %= MOD;
  while (e > 0n) {
    if (e & 1n) r = r * b % MOD;
    b = b * b % MOD;
    e >>= 1n;
  }
  return r;
}
const invFact = new Array(top + 1);
invFact[top] = power(fact[top], MOD - 2n);
for (let i = top; i >= 1; i--) invFact[i - 1] = invFact[i] * BigInt(i) % MOD;
const out = [];
for (let i = 0; i < q; i++) {
  const n = tok[1 + 2 * i], k = tok[2 + 2 * i];
  if (k > n) out.push('0');
  else out.push((fact[n] * invFact[k] % MOD * invFact[n - k] % MOD).toString());
}
console.log(out.join('\n'));

