import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;
    static long power(long b, long e) {
        long r = 1;
        b %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % MOD;
            b = b * b % MOD;
            e >>= 1;
        }
        return r;
    }
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedInputStream(System.in));
        st.nextToken();
        int q = (int) st.nval;
        int[] ns = new int[q], ks = new int[q];
        int top = 0;
        for (int i = 0; i < q; i++) {
            st.nextToken(); ns[i] = (int) st.nval;
            st.nextToken(); ks[i] = (int) st.nval;
            top = Math.max(top, ns[i]);
        }
        long[] fact = new long[top + 1], invFact = new long[top + 1];
        fact[0] = 1;
        for (int i = 1; i <= top; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[top] = power(fact[top], MOD - 2);
        for (int i = top; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            long v = ks[i] > ns[i] ? 0 : fact[ns[i]] * invFact[ks[i]] % MOD * invFact[ns[i] - ks[i]] % MOD;
            sb.append(v).append('\n');
        }
        System.out.print(sb);
    }
}

