#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1000000007LL;
ll power(ll b, ll e) {
    ll r = 1;
    b %= MOD;
    while (e > 0) {
        if (e & 1) r = r * b % MOD;
        b = b * b % MOD;
        e >>= 1;
    }
    return r;
}
int main() {
    int q;
    scanf("%d", &q);
    vector<int> ns(q), ks(q);
    int top = 0;
    for (int i = 0; i < q; i++) {
        scanf("%d %d", &ns[i], &ks[i]);
        top = max(top, ns[i]);
    }
    vector<ll> fact(top + 1), invFact(top + 1);
    fact[0] = 1;
    for (int i = 1; i <= top; i++) fact[i] = fact[i - 1] * i % MOD;
    invFact[top] = power(fact[top], MOD - 2);
    for (int i = top; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;
    for (int i = 0; i < q; i++) {
        ll v = ks[i] > ns[i] ? 0 : fact[ns[i]] * invFact[ks[i]] % MOD * invFact[ns[i] - ks[i]] % MOD;
        printf("%lld\n", v);
    }
    return 0;
}
